    op[op, v[0, 1], 1, -1]] + sum[F[phi, phi, phi, phi]*
     \[Beta][op[phi, v[1, 0], 1, 1], op[phi, v[1, 0], 1, 1],
        op[op, v[1, 0], 1, -1]][1]^2, op[op, v[1, 0], 1, -1]] +
   (7*sum[F[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
          op[phi, v[1, 0], 1, 1], op[op, v[2, 0], 1, 1]][1]^2,
      op[op, v[2, 0], 1, 1]])/9, single[Fp[phi, phi, phi, phi, 0]] +
   single[Fp[phi, phi, phi, phi, s]*
      \[Beta][op[phi, v[1, 0], 1, 1], op[phi, v[1, 0], 1, 1],
         op[s, v[0, 0], 1, 1]][1]^2]/7 +
   sum[F[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
         op[phi, v[1, 0], 1, 1], op[op, v[0, 0], 1, 1]][1]^2,
     op[op, v[0, 0], 1, 1]]/7 +
   (2*sum[F[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
          op[phi, v[1, 0], 1, 1], op[op, v[2, 0], 1, 1]][1]^2,
      op[op, v[2, 0], 1, 1]])/63, single[Fp[s, s, phi, phi, 0]] +
   single[Fp[s, phi, phi, s, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
