      \[Beta][op[s, v[0, 0], 1, 1], op[s, v[0, 0], 1, 1],
        op[op, v[0, 0], 1, 1]][1], op[op, v[0, 0], 1, 1]]/Sqrt[7],
  single[Fp[s, s, s, s, 0]] + single[Fp[s, s, s, s, s]*
     \[Beta][op[s, v[0, 0], 1, 1], op[s, v[0, 0], 1, 1],
