   sum[F[s, s, s, s]*\[Beta][op[s, v[0, 0], 1, 1], op[s, v[0, 0], 1, 1],
        op[op, v[0, 0], 1, 1]][1]^2, op[op, v[0, 0], 1, 1]],
  sum[H[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
        op[phi, v[1, 0], 1, 1], op[op, v[0, 1], 1, -1]][1]^2,
    op[op, v[0, 1], 1, -1]] -
   2*sum[H[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
