     op[op, v[1, 0], 1, -1]], single[Hp[phi, phi, phi, phi, 0]] +
   single[Hp[phi, phi, phi, phi, s]*
      \[Beta][op[phi, v[1, 0], 1, 1], op[phi, v[1, 0], 1, 1],
         op[s, v[0, 0], 1, 1]][1]^2]/7 +
   sum[H[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
         op[phi, v[1, 0], 1, 1], op[op, v[0, 0], 1, 1]][1]^2,
     op[op, v[0, 0], 1, 1]]/7 +
   sum[H[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
         op[phi, v[1, 0], 1, 1], op[op, v[1, 0], 1, -1]][1]^2,
     op[op, v[1, 0], 1, -1]]/14 -
   sum[H[phi, phi, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
         op[phi, v[1, 0], 1, 1], op[op, v[2, 0], 1, 1]][1]^2,
     op[op, v[2, 0], 1, 1]]/42, single[Hp[s, s, phi, phi, 0]] -
   single[Hp[s, phi, phi, s, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
         op[phi, v[1, 0], 1, 1], op[s, v[0, 0], 1, 1]][1]^2]/7 +
   single[Hp[s, s, phi, phi, s]*\[Beta][op[phi, v[1, 0], 1, 1],
        op[phi, v[1, 0], 1, 1], op[s, v[0, 0], 1, 1]][1]*
      \[Beta][op[s, v[0, 0], 1, 1], op[s, v[0, 0], 1, 1],
        op[s, v[0, 0], 1, 1]][1]]/Sqrt[7] +
   sum[H[s, phi, phi, s]*\[Beta][op[s, v[0, 0], 1, 1], op[phi, v[1, 0], 1,
          1], op[op, v[1, 0], 1, -1]][1]^2, op[op, v[1, 0], 1, -1]]/7 -
   sum[H[s, phi, phi, s]*\[Beta][op[s, v[0, 0], 1, 1], op[phi, v[1, 0], 1,
          1], op[op, v[1, 0], 1, 1]][1]^2, op[op, v[1, 0], 1, 1]]/7 +
   sum[H[s, s, phi, phi]*\[Beta][op[phi, v[1, 0], 1, 1],
